<script setup>
import { useForm, router } from '@inertiajs/vue3'; import AdminLayout from '../../../Layouts/AdminLayout.vue'; defineProps({categories:Array}); const form=useForm({name_bn:'',name_en:'',type:'book'}); const add=()=>form.post('/admin/categories',{onSuccess:()=>form.reset()}); const remove=id=>router.delete(`/admin/categories/${id}`);
</script>
<template><AdminLayout><h1 class="font-serif text-4xl">ক্যাটাগরি</h1><div class="mt-8 grid gap-8 md:grid-cols-[1fr_1.5fr]"><form @submit.prevent="add" class="rounded-2xl bg-white p-6"><h2 class="font-semibold">নতুন ক্যাটাগরি</h2><input v-model="form.name_bn" required placeholder="বাংলা নাম" class="field" /><input v-model="form.name_en" required placeholder="English name" class="field" /><select v-model="form.type" class="field"><option value="book">বই</option><option value="post">পোস্ট</option></select><button class="mt-3 rounded-full bg-[#1d4843] px-5 py-2.5 text-sm font-semibold text-white">যোগ করুন</button></form><div class="rounded-2xl bg-white p-6"><div v-for="c in categories" :key="c.id" class="flex items-center justify-between border-b border-[#edf0eb] py-4"><span><b>{{ c.name_bn }}</b><small class="ml-3 text-[#87938d]">{{ c.type }}</small></span><button @click="remove(c.id)" class="text-sm text-red-600">মুছুন</button></div></div></div></AdminLayout></template><style scoped>.field{display:block;margin-top:.75rem;width:100%;border:0;border-radius:.5rem;background:#f7f5f0;padding:.75rem 1rem;box-shadow:inset 0 0 0 1px #dfe1d8}</style>
